  if (uangBesarKeluar) { alasan.push(`porsi ${dAsing != null && dAsing <= -0.3 ? 'asing' : 'institusi lokal'} turun ${Math.abs(Math.min(dAsing || 0, dInst || 0)).toFixed(2)} poin sebulan`); if (!tone) { vonis = 'UANG BESAR KELUAR'; tone = 'bad'; } }
